} datasource db { provider = "postgresql" } model User {
id Int @id @default(autoincrement()) email String @unique name String? age Int?
active Boolean @default(true) createdAt DateTime @default(now()) tags String[]
profile Json? posts Post[] } model Post {
id Int @id @default(autoincrement()) title String published Boolean
@default(false) authorId Int author User @relation(fields: [authorId],
references: [id]) }

import "dotenv/config"; import { defineConfig, env } from "prisma/config";
export default defineConfig({ schema: "prisma/schema.prisma", migrations: {
path: "prisma/migrations" }, datasource: { url: env("DATABASE_URL") } });

import "dotenv/config"; import { PrismaClient }
from "./generated/prisma/client"; import { PrismaPg } from "@prisma/adapter-pg";
const connectionString = process.env.DATABASE_URL;
if (!connectionString) throw new Error("DATABASE_URL is required");
const adapter = new PrismaPg({ connectionString });
const prisma = new PrismaClient({ adapter });

await prisma.$transaction([prisma.user.update({ where: { id: 1 }, data: {
active: true } }), prisma.post.updateMany({ where: { authorId: 1 }, data: {
published: true } })]);

await prisma.$transaction(async (tx) => { const user = await tx.user.create({
data: { email: 'tx@example.com', tags: [] } }); await tx.post.create({ data: {
title: 'Hello', authorId: user.id } }); });

import { Prisma } from './generated/prisma/client'; try {
await prisma.user.create({ data: { email: 'pomo@example.com', tags: [] } }); }
catch (e) { if (e instanceof Prisma.PrismaClientKnownRequestError && e.code ===
'P2002') { console.log('一意制約違反'); } else { throw e; } }
